ayment Schedule", "notes_region": true, "tracking": {"start": "Tracking Number\\(s\\):", "token": "\\b(1Z[0-9A-Z]{16}|\\d{12,22})\\b"}, "totals_page": "last", "totals": {"merchandise": "\\bMDSE\\s+(-?[\\d,]+\\.\\d{2}-?)\\s*$", "freight": "\\bFREIGHT\\s+(-?[\\d,]+\\.\\d{2}-?)\\s*$", "other": "\\bOTHER\\s+(-?[\\d,]+\\.\\d{2}-?)\\s*$", "tax": "\\bTAX\\s+(-?[\\d,]+\\.\\d{2}-?)\\s*$", "total": "\\bTOTAL\\s+(-?[\\d,]+\\.\\d{2}-?)\\s*$"}, "payment_schedule": {"after": "Payment Schedule", "regex": "(\\d{2}/\\d{2}/\\d{4})\\s+(-?[\\d,]+\\.\\d{2})\\s*(?:OTHER|TAX|FREIGHT|$)"}, "ignore_lines": ["^\\s*Page\\s+\\d+\\s+of", "instructions\\. Be wary", "surcharges on debit cards", "Visa, Ma(sterCard)?", "Beginning November 1, 2018", "^\\s*\\*\\s*\\*\\s*\\*\\s*PLEA"], "line_flags": {"*": "usitc_tariff_item"}, "totals_labels": {"other": "Tariff surcharge on asterisked USITC items (since 2025)"}}, {"id": "amer_portal", "description": "Newer Amer Sports billing-portal invoice (header + total only, no line detail). Seen on some 2026 debit memos.", "match": "Invoice Date\\s+\\d{4}-\\d{2}-\\d{2}", "doc_type": {"INVOICE": "invoice"}, "date_format": "%Y-%m-%d", "header": {"invoice_number": "Invoice #\\s+(\\d+)", "invoice_date": "Invoice Date\\s+(\\d{4}-\\d{2}-\\d{2})", "due_date": "Due Date\\s+(\\d{4}-\\d{2}-\\d{2})"}, "line_item": null, "totals": {"merchandise": "Subtotal:\\s+U?\\$?([\\d,]+\\.\\d{2})", "total": "Total:\\s+U?\\$?([\\d,]+\\.\\d{2})"}, "review_reason": "Portal invoice has no line detail — needs the matching SAP debit memo/invoice or manual lines."}], "unsupported_patterns": {"OFFICIAL PAYMENT RECEIPT": "Payment receipt (Wilson Stringing) — not a vendor bill"}, "terms_parse": [{"regex": "(\\d+(?:\\.\\d+)?)\\s*%\\s*(\\d+)\\s*,\\s*net\\s*(\\d+)", "disc_pct": 1, "disc_days": 2, "net_days": 3}, {"regex": "net\\s*(\\d+)", "net_days": 1}], "product_match": {"shopify_vendor": ["Wilson"], "attributes": [{"name": "grip", "from": "description", "regex": "(?:FRM|DEMO|BKBL)\\s+([0-5])$|^(?:.*\\b(?:BLADE|CLASH|PRO STAFF|BURN|SHIFT|ULTRA|RF 01)\\b.*)\\s([0-5])$", "map": {"0": ["4", "l0", "0"], "1": ["4 1/8", "l1", "1"], "2": ["4 1/4", "l2", "2"], "3": ["4 3/8", "l3", "3"], "4": ["4 1/2", "l4", "4"], "5": ["4 5/8", "l5", "5"]}}, {"name": "size", "from": "sku", "regex": "^WRS\\d+U(\\d{3})$", "transform": "size_tenths"}]}}, "qbo_vendor": "Wilson Sporting Goods", "notes": "45 sample invoices 2023-06 → 2026-09, Dropbox Invoices/1 - Processed/Wilson", "by": "Invoice Lab import"}$TPL$::jsonb);
select jt.invoice_template_put($TPL${"vendor": "Yonex", "slug": "yonex", "template": {"slug": "yonex", "version": "1.0", "vendor_name": "Yonex Corporation", "parser": "layout_text", "learned_from": "250 files 2023-05 -> 2026-09: 'Customer Copy' invoice print (mostly scanned on a ScanSnap → OCR) and biz.yonexusa.net web reprints; customer 1442092", "identify": {"all": ["Yonex|YONEX|1442092"], "any": ["Torrance", "Yonex Corporation", "yonexusa", "Customer #: 1442092", "1442092"]}, "variants": [{"id": "customer_copy", "match": "Multiplier|Backordered|UPC Vendor", "date_format": "%m/%d/%y", "header": {"invoice_number": "(\\d{6}-\\d{2})\\b", "invoice_date": "(\\d{2}/\\d{2}/\\d{2})\\s+\\d{6}-\\d{2}"}, "row_after_header": {"po": {"header": "PO Date\\s+PO #", "regex": "^\\s*(?P<order_date>\\d{2}/\\d{2}/\\d{2})\\s+(?P<po_reference>\\S.*?)\\s{2,}\\d+\\s*$"}, "ship": {"header": "Ship\\s*Point|Via\\s+Sh\\w{2,4}ed\\s+T", "regex": "Yonex USA\\s+(?P<ship_via>\\S+)\\s+(?P<ship_date>\\d{2}/\\d{2}/\\d{2})\\s+(?P<terms>\\S.*?)\\s*$"}}, "line_region_start": "Multiplier\\s*\\W?\\s*N[eo]t|\\W[NM]et\\W?\\s*$|Shipped\\s+UM\\s+Price", "line_region_end": "Lines Total|Print Time", "line_item": {"regex": "^\\W{0,3}(?P<ln>\\d{1,3})\\s*(?:[^\\sA-Za-z0-9]{1,3}|_)?\\s*(?P<vendor_sku>[A-Z0-9][A-Za-z0-9\\-_]{3,})\\b.*?\\s\\W?(?P<list_price>\\d[\\d,]*\\.\\d{2})\\W*\\s+(?:[^\\d\\n$]{0,40}?)(?:(?P<discount_pct>\\d{1,3}\\.\\d{2})\\W*\\s+[^\\d\\n$]{0,40}?)?(?P<extended_cost>\\$?[\\d,]+\\.\\d{2})\\W*\\s*$", "sku_tokens_until": "[0OoCcen|]{3,6}|\\W*\\d+\\W*|[Tt]oo|[|\\]\\[]", "qty_from_price_discount": true, "description": "next_line", "description_min_indent": 0, "drop_zero_qty": true, "unit_from_extended": true}, "totals_page": "last", "totals": {"merchandise": "Qty Shipped Tota\\S*\\s+\\S+\\s+Tota\\S*\\s+([\\d,]+\\.\\d{2})", "freight": "Freight[^\\d\\n]*?([\\d,]+\\.\\d{2})\\s*$", "total": "Invoice Total\\s+([\\d,]+\\.\\d{2})"}, "header_fallback": {"invoice_number": ["file:_(\\d{6}-\\d{2})\\b", "(\\d{6}-\\d{2})"], "invoice_date": ["Yonex\\s*USA\\s+\\S+\\s+(\\d{2}/\\d{2}/\\d{2})", "(\\d{2}/\\d{2}/\\d{2})\\s+Net\\s*\\d", "(\\d{2}/\\d{2}/\\d{2})\\s+\\W{0,3}\\d{6}-\\d{2}"]}}, {"id": "web_reprint", "match": "INVOICE - Web Reprint", "date_format": "%m/%d/%Y", "header": {"invoice_number": "Invoice #:\\s*(\\d{6}-\\d{2})", "invoice_date": "Invoice Date:\\s*(\\d{2}/\\d{2}/\\d{4})", "terms": "Terms:\\s*(\\S+)", "po_reference": "Customer PO:\\s*(\\S[^\\n]*?)\\s*$"}, "line_region_start": "Line\\s+Order\\s+Ship\\s+Item#", "line_region_end": "Subtotal\\s+\\$", "ignore_lines": ["Customer Invoice History", "^https?://"], "line_item": {"regex": "^\\s*(?P<ln>\\d+)\\s+(?P<qty_ordered>\\d+)\\s+(?P<qty>\\d+)\\s+(?P<vendor_sku>[0-9A-Z][0-9A-Z\\-_]*?)(?:\\s+(?P<description>\\S.*?))?\\s+\\$(?P<unit_cost>[\\d,]+\\.\\d{2})\\s+\\$(?P<extended_cost>[\\d,]+\\.\\d{2})\\s*$", "partial_regex": "^\\s*(?P<ln>\\d+)\\s+(?P<qty_ordered>\\d+)\\s+(?P<qty>\\d+)\\s+(?P<vendor_sku>[0-9A-Z][0-9A-Z\\-_]*)(?:\\s+(?P<description>\\S.*?))?\\s*$", "fill_regex": ["^(?P<description>.*?)\\$(?P<unit_cost>[\\d,]+\\.\\d{2})\\s+\\$(?P<extended_cost>[\\d,]+\\.\\d{2})\\s*$"], "description": "inline", "wrap_fields": {"vendor_sku": ""}, "wrap_tolerance": 1, "drop_zero_qty": true, "unit_from_extended": true}, "totals_page": "last", "totals": {"merchandise": "Subtotal\\s+\\$([\\d,]+\\.\\d{2})", "freight": "FREIGHT\\s+\\$([\\d,]+\\.\\d{2})", "tax": "(?m)\\sTax\\s+\\$([\\d,]+\\.\\d{2})\\s*$", "total": "(?m)\\s{2,}Total\\s+\\$([\\d,]+\\.\\d{2})\\s*$"}}]}, "qbo_vendor": "Yonex", "notes": "250 files 2023-05 -> 2026-09: 'Customer Copy' invoice print (mostly scanned on a ScanSnap → OCR) and biz.yonexusa.net web reprints; customer 1442092", "by": "Invoice Lab import"}$TPL$::jsonb);
